fn collect_rects(paths: &[Vec<super::types::Point64>]) -> Option<Vec<Rect64>> {
    paths.iter().map(Rect64::from_path).collect()
}

fn merged_rectangles(mut rects: Vec<Rect64>) -> Vec<Rect64> {
    if rects.is_empty() {
        return rects;
    }

    rects.sort_by_key(|rect| (rect.top, rect.bottom, rect.left, rect.right));

    let mut horizontal: Vec<Rect64> = Vec::new();
    for rect in rects {
        if let Some(last) = horizontal.last_mut() {
            if last.top == rect.top && last.bottom == rect.bottom && last.right == rect.left {
                last.right = rect.right;
                continue;
            }
        }
        horizontal.push(rect);
    }

    horizontal.sort_by_key(|rect| (rect.left, rect.right, rect.top, rect.bottom));

    let mut vertical: Vec<Rect64> = Vec::new();
    for rect in horizontal {
        if let Some(last) = vertical.last_mut() {
            if last.left == rect.left && last.right == rect.right && last.bottom == rect.top {
                last.bottom = rect.bottom;
                continue;
            }
        }
        vertical.push(rect);
    }

    vertical
}

fn boolean_rect_op<F>(subjects: &[Vec<super::types::Point64>], clips: &[Vec<super::types::Point64>], predicate: F) -> Paths64
where
    F: Fn(bool, bool) -> bool,
{
    let subject_rects = match collect_rects(subjects) {
        Some(rects) => rects,
        None => return Vec::new(),
    };
    let clip_rects = match collect_rects(clips) {
        Some(rects) => rects,
        None => return Vec::new(),
    };

    let mut xs = Vec::with_capacity((subject_rects.len() + clip_rects.len()) * 2);
    let mut ys = Vec::with_capacity((subject_rects.len() + clip_rects.len()) * 2);

    for rect in subject_rects.iter().chain(clip_rects.iter()) {
        xs.push(rect.left);
        xs.push(rect.right);
        ys.push(rect.top);
        ys.push(rect.bottom);
    }

    xs.sort_unstable();
    xs.dedup();
    ys.sort_unstable();
    ys.dedup();

    let mut cells = Vec::new();
    for y_pair in ys.windows(2) {
        for x_pair in xs.windows(2) {
            let cell = Rect64 {
                left: x_pair[0],
                top: y_pair[0],
                right: x_pair[1],
                bottom: y_pair[1],
            };

            let in_subject = subject_rects.iter().any(|rect| rect.contains_cell(cell));
            let in_clip = clip_rects.iter().any(|rect| rect.contains_cell(cell));

            if predicate(in_subject, in_clip) {
                cells.push(cell);
            }
        }
    }

    merged_rectangles(cells)
        .into_iter()
        .map(Rect64::to_path)
        .collect()
}

#[allow(non_snake_case)]
pub fn Intersect(subjects: &[Vec<super::types::Point64>], clips: &[Vec<super::types::Point64>], fill_rule: FillRule) -> Paths64 {
    let _ = fill_rule;
    boolean_rect_op(subjects, clips, |in_subject, in_clip| in_subject && in_clip)
}

#[allow(non_snake_case)]
pub fn Union(subjects: &[Vec<super::types::Point64>], clips: &[Vec<super::types::Point64>], fill_rule: FillRule) -> Paths64 {
    let _ = fill_rule;
    boolean_rect_op(subjects, clips, |in_subject, in_clip| in_subject || in_clip)
}

#[allow(non_snake_case)]
pub fn Difference(subjects: &[Vec<super::types::Point64>], clips: &[Vec<super::types::Point64>], fill_rule: FillRule) -> Paths64 {
    let _ = fill_rule;
    boolean_rect_op(subjects, clips, |in_subject, in_clip| in_subject && !in_clip)
}

#[allow(non_snake_case)]
pub fn Xor(subjects: &[Vec<super::types::Point64>], clips: &[Vec<super::types::Point64>], fill_rule: FillRule) -> Paths64 {
    let _ = fill_rule;
    boolean_rect_op(subjects, clips, |in_subject, in_clip| in_subject ^ in_clip)
}

use super::types::{Path64, Point64};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct Rect64 {
    pub left: i64,
    pub top: i64,
    pub right: i64,
    pub bottom: i64,
}

#[allow(dead_code)]
impl Rect64 {
    pub fn from_path(path: &Path64) -> Option<Self> {
        if path.len() != 4 {
            return None;
        }

        let mut xs = [path[0].x, path[1].x, path[2].x, path[3].x];
        let mut ys = [path[0].y, path[1].y, path[2].y, path[3].y];
        xs.sort_unstable();
        ys.sort_unstable();

        if xs[0] == xs[3] || ys[0] == ys[3] {
            return None;
        }

        let left = xs[0];
        let right = xs[3];
        let top = ys[0];
        let bottom = ys[3];

        let corners = [
            Point64::new(left, top),
            Point64::new(right, top),
            Point64::new(right, bottom),
            Point64::new(left, bottom),
        ];

        if path.iter().all(|point| corners.contains(point)) {
            Some(Self {
                left,
                top,
                right,
                bottom,
            })
        } else {
            None
        }
    }

    pub const fn intersects(self, other: Self) -> bool {
        self.left < other.right
            && other.left < self.right
            && self.top < other.bottom
            && other.top < self.bottom
    }

    pub const fn intersection(self, other: Self) -> Option<Self> {
        let left = if self.left > other.left {
            self.left
        } else {
            other.left
        };
        let top = if self.top > other.top {
            self.top
        } else {
            other.top
        };
        let right = if self.right < other.right {
            self.right
        } else {
            other.right
        };
        let bottom = if self.bottom < other.bottom {
            self.bottom
        } else {
            other.bottom
        };

        if left < right && top < bottom {
            Some(Self {
                left,
                top,
                right,
                bottom,
            })
        } else {
            None
        }
    }

    pub fn to_path(self) -> Path64 {
        vec![
            Point64::new(self.left, self.top),
            Point64::new(self.right, self.top),
            Point64::new(self.right, self.bottom),
            Point64::new(self.left, self.bottom),
        ]
    }

    pub const fn contains_cell(self, cell: Self) -> bool {
        cell.left >= self.left
            && cell.right <= self.right
            && cell.top >= self.top
            && cell.bottom <= self.bottom
    }
}
